// The expectations of tests/cases/libc-format/fixed.txt (#1139 area 14), written by glibc 2.40's snprintf: `cc -w fixed.c && ./a.out > fixed.txt`.
// They are kept as a table, not regenerated by tools/test-libc-format.sh, because they are formats whose result glibc's versions disagree on or that
// the random cases cannot pass: a format that ends inside a conversion, C23's wN lengths and %b, widths, precisions and counts past INT_MAX (-1,
// EOVERFLOW), and long doubles (x:<16 bytes>, a value a double holds exactly: the static libc formats a long double as the nearest double).
// A line: size, format (hex), arguments, then glibc's result and the buffer (hex); for a result of -1 only the result is compared.
#include <stdio.h>
#include <string.h>
#include <stdint.h>
static char b[1<<16];
static void hx(const char*s){for(const unsigned char*p=(const unsigned char*)s;*p;p++)printf("%02x",*p);}
static void ld(long double v){unsigned char x[16]={0};memcpy(x,&v,10);printf("x:");for(int i=0;i<16;i++)printf("%02x",x[i]);printf(" ");}
#define CASE(SIZE, FMT, ARGSTR, ...) do { memset(b,0,sizeof b); int r = snprintf(b, SIZE, FMT, __VA_ARGS__); printf("%d\t", SIZE); hx(FMT); printf("\t"); ARGSTR; printf("\t%d\t", r); hx(b); printf("\n"); } while (0)
int main(){
 CASE(64,"ab%",printf(" "),0);
 CASE(64,"ab%-5",printf(" "),0);
 CASE(64,"ab%l",printf(" "),0);
 CASE(64,"ab%.",printf(" "),0);
 CASE(64,"%w32d|%wf8u|%w64x|%w16d|%s",printf("i:-5 i:300 i:-1 i:65535 s:6f6b "),-5,300,-1LL,65535,"ok");
 CASE(64,"a%w7d",printf("i:1 "),1);
 CASE(64,"a%w",printf("i:1 "),1);
 CASE(64,"%#b|%B|%.0b|%hhb|%s",printf("i:5 i:0 i:0 i:258 s:6f6b "),5,0,0,258,"ok");
 CASE(64,"x%2147483648d",printf("i:1 "),1);
 CASE(64,"x%.2147483648d",printf("i:1 "),1);
 CASE(64,"x%99999999999999999999d",printf("i:1 "),1);
 CASE(64,"%2147483647d%d",printf("i:1 i:1 "),1,1);
 CASE(64,"%2147483647d",printf("i:1 "),1);
 CASE(64,"%*d",printf("i:-2147483648 i:1 "),INT32_MIN,1);
 CASE(64,"%.2147483647d|",printf("i:5 "),5);
 CASE(64,"%Lf|%s",(ld(1.5L),printf("s:6f6b ")),1.5L,"ok");
 CASE(64,"%d %Lf %d %.3Le %d",(printf("i:7 "),ld(-0.25L),printf("i:8 "),ld(1e300L),printf("i:9 ")),7,-0.25L,8,1e300L,9);
 CASE(64,"%Lg|%010.2Lf|%-8Lf|",(ld(0.1L),ld(-3.0L),ld(1.0L/0.0L)),0.1L,-3.0L,1.0L/0.0L);
 CASE(64,"%Lf %LF %Le",(ld(-(0.0L/0.0L)),ld(2.0L/0.0L),ld(5e-310L)),-(0.0L/0.0L),2.0L/0.0L,5e-310L);
}
